method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1])
{
    var maxVal := numbers[0];
    result := new int[|numbers|];

    var i := 0;
    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant result[0..i] == [Max(numbers[0..j+1]) | j | 0 <= j < i]
    {
        if numbers[i] > maxVal {
            maxVal := numbers[i];
        }
        result[i] := maxVal;
        i := i + 1;
    }
}
```

problem_data.canonical_solution:
running_max = None
result = []

for n in numbers:
    if running_max is None:
        running_max = n
    else:
        running_max = max(running_max, n)

    result.append(running_max)

return result

